materials.vertexShader:
uniform float uKind; varying vec3 vNormal; varying vec3 vView; varying vec3 vLocal;
        void main() { float deformation = uKind > 2.5 ? 0.012*sin(position.x*13.0+sin(position.y*11.0))*cos(position.z*9.0) : 0.0;
          vec4 p=modelViewMatrix*vec4(position*(1.0+deformation),1.0); vNormal=normalize(normalMatrix*normal);
          vView=-p.xyz; vLocal=position; gl_Position=projectionMatrix*p; }

materials.fragmentShader:
uniform vec3 uColor; uniform vec3 uCoolColor; uniform vec3 uHotColor; uniform float uThermalPhase; uniform float uStrength; uniform float uGranulation; uniform float uKind; uniform float uTime;
        varying vec3 vNormal; varying vec3 vView; varying vec3 vLocal;
        float hash(vec3 p) { return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453); }
        float noise(vec3 p) { vec3 i=floor(p),f=fract(p); f=f*f*(3.0-2.0*f);
          return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),
            mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z); }
        void main() { float mu=max(0.0,dot(normalize(vNormal),normalize(vView)));
          float limb=(2.0+3.0*mu)/5.0;
          vec3 drift=vec3(0.0,uTime*0.045,uTime*0.018);
          vec3 cells=vLocal*24.0 + vec3(noise(vLocal*5.0+drift)-0.5)*1.8;
          float fine=noise(cells*2.7+drift*0.65);
          float convection=noise(cells+drift);
          float lane=1.0-smoothstep(0.28,0.48,convection);
          float grain=(convection*.7+fine*.3)*2.0-1.0;
          float structure=1.0+uGranulation*grain-lane*0.24;
          if (uKind > 0.5 && uKind < 1.5) {
            vec3 cloud = vLocal; float angle = uTime*0.025;
            cloud.xz = mat2(cos(angle),-sin(angle),sin(angle),cos(angle))*cloud.xz;
            float bands = sin(cloud.y*29.0 + 3.0*noise(cloud*7.0));
            float haze = noise(cloud*20.0)*0.65 + noise(cloud*42.0)*0.35;
            structure = 0.91 + 0.12*bands + 0.08*(haze-0.5);
          } else if (uKind > 1.5 && uKind < 2.5) {
            float latitude = abs(vLocal.y);
            float polar = smoothstep(0.66,0.88,latitude)*(0.5+0.5*sin(atan(vLocal.z,vLocal.x)*3.0));
            structure += polar*0.11;
          } else if (uKind > 2.5) {
            float giantCells = noise(vLocal*6.0+drift*.3)*.7+noise(vLocal*13.0+drift*.2)*.3;
            structure = 0.64+0.52*giantCells+grain*0.06;
          }
          vec3 thermalColor = uThermalPhase >= 0.0 ? mix(uColor,uHotColor,uThermalPhase) : mix(uColor,uCoolColor,-uThermalPhase);
          gl_FragColor=vec4(thermalColor*uStrength*limb*structure,1.0);
          #include <tonemapping_fragment>
          #include <colorspace_fragment>
        }

uniform vec3 uColor; uniform float uOpacity; varying vec3 vNormal; varying vec3 vView; void main(){
      float mu=max(0.0,dot(normalize(vNormal),normalize(vView)));
      float density=pow(1.0-mu,2.0);
      gl_FragColor=vec4(uColor,uOpacity*density);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
    }

materials.vertexShader:
attribute float aPhase; uniform float uTime; uniform float uRadius; uniform float uKind; uniform float uPixelRatio;
      varying float vFade; void main() {
        float phase=fract(aPhase+uTime*0.045); vec3 p;
        if(uKind<0.5) { p=position*uRadius*(1.15+phase*2.5); vFade=sin(phase*3.14159)*(1.0-phase)*0.16; }
        else if(uKind<1.5) { float signY=position.y<0.0?-1.0:1.0;
          float distance=0.9+phase*3.5; float width=0.025+distance*0.085;
          p=vec3(position.x*width,signY*distance,position.z*width)*uRadius;
          vFade=(1.0-phase)*0.85; }
        else { float r=1.35+aPhase*1.9; float a=atan(position.z,position.x)+uTime*0.35/pow(r,1.5);
          p=vec3(cos(a)*r,position.y*0.035,sin(a)*r)*uRadius; vFade=0.3+0.4*(1.0-aPhase); }
        gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.0);
        gl_PointSize=(uKind>0.5&&uKind<1.5?3.0:2.0)*uPixelRatio;
      }

materials.fragmentShader:
uniform vec3 uColor; varying float vFade; void main() {
      float r=length(gl_PointCoord*2.0-1.0); if(r>1.0) discard;
      gl_FragColor=vec4(uColor,exp(-r*r*4.5)*vFade);
      #include <tonemapping_fragment>
      #include <colorspace_fragment>
    }

uniform vec3 uColor; uniform float uTime; uniform float uSpeed; uniform float uOpacity; varying vec2 vUv;
      void main(){float packets=pow(0.5+0.5*cos((vUv.x-uTime*uSpeed)*37.6991),5.0);
        float crossSection=0.5+0.5*sin(vUv.y*6.283185);
        gl_FragColor=vec4(uColor,(0.13+0.87*packets)*uOpacity*crossSection);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
